def predict_final(input_grid):
    rows = len(input_grid)
    cols = len(input_grid[0])
    output = [[0]*cols for _ in range(rows)]

    # Step 1: Start as all 1s
    for r in range(rows):
        for c in range(cols):
            output[r][c] = 1

    # Step 2: Mark 2s
    for r in range(rows):
        for c in range(cols):
            if input_grid[r][c] == 2:
                output[r][c] = 2

    # Step 3: Find horizontal "between 2s" regions
    for r in range(rows):
        two_positions = [c for c in range(cols) if input_grid[r][c] == 2]
        for i in range(len(two_positions)):
            for j in range(i+1, len(two_positions)):
                # Check if cells between are clear of 2s
                is_clear = True
                for k in range(two_positions[i]+1, two_positions[j]):
                    if input_grid[r][k] == 2:
                        is_clear = False
                        break
                if is_clear:
                    for k in range(two_positions[i]+1, two_positions[j]):
                        output[r][k] = 3

    # Step 4: Find vertical "between 2s" regions
    for c in range(cols):
        two_positions = [r for r in range(rows) if input_grid[r][c] == 2]
        for i in range(len(two_positions)):
            for j in range(i+1, len(two_positions)):
                # Check if cells between are clear of 2s
                is_clear = True
                for k in range(two_positions[i]+1, two_positions[j]):
                    if input_grid[k][c] == 2:
                        is_clear = False
                        break
                if is_clear:
                    for k in range(two_positions[i]+1, two_positions[j]):
                        output[k][c] = 3

    return output

